<script setup lang="ts">
import { computed, ref } from 'vue';
import DelayedTooltip from '../tooltip/DelayedTooltip.vue';
import type { SettingsTarget } from './types';
const props=defineProps<{tags?:readonly string[];allProfiles:boolean;otherTarget?:SettingsTarget;configured:boolean}>();
const emit=defineEmits<{scope:[target:SettingsTarget]}>();
const root=ref<HTMLElement>(),profile=ref<HTMLElement>();const focused=ref(0),elements=ref<Record<string,HTMLElement>>({});
const badges=computed(()=>{const badges=[];if(props.tags?.includes('preview'))badges.push({label:'Preview',text:'Preview setting: this setting controls a new feature that is still under refinement yet ready to use. Feedback is welcome.'});else if(props.tags?.includes('experimental'))badges.push({label:'Experimental',text:'Experimental setting: this setting controls a new feature that is actively being developed and may be unstable. It is subject to change or removal.'});if(props.tags?.includes('advanced'))badges.push({label:'Advanced',text:'Advanced setting: this setting is intended for advanced scenarios and configurations. Only modify this if you know what it does.'});return badges;});
const visible=computed(()=>badges.value.length||props.allProfiles||props.otherTarget);
function navigate(event:KeyboardEvent){const targets=Array.from(root.value?.querySelectorAll<HTMLElement>('[data-indicator]')||[]);let index=focused.value;if(event.key==='Home')index=0;else if(event.key==='End')index=targets.length-1;else if(event.key==='ArrowRight')index=(index+1)%targets.length;else if(event.key==='ArrowLeft')index=(index+targets.length-1)%targets.length;else return;focused.value=index;targets.forEach((target,i)=>target.tabIndex=i===index?0:-1);targets[index]?.focus();event.preventDefault();event.stopPropagation();}
</script>
<template><span ref="root" class="setting-indicators-container" :style="{display:visible?'inline':'none'}" :role="visible?'toolbar':'button'" @keydown="navigate"><span v-for="(badge,index) in badges" :key="badge.label" :ref="element=>{if(element)elements[badge.label]=element as HTMLElement}" class="setting-indicator setting-item-preview" data-indicator :tabindex="index===focused?0:-1">{{badge.label}}<DelayedTooltip :target="elements[badge.label]" :text="badge.text" /></span><template v-if="allProfiles||otherTarget"><span>(</span><span v-if="allProfiles" ref="profile" class="setting-item-overrides setting-indicator" style="display:inline" data-indicator :tabindex="focused===badges.length?0:-1">Applies to all profiles<DelayedTooltip :target="profile" text="The setting is not specific to the current profile, and will retain its value when switching profiles." /></span><span v-else class="setting-item-overrides" style="display:inline">{{configured?'Also modified in ':'Modified in '}}<a class="modified-scope" data-indicator :tabindex="focused===badges.length?0:-1" @click.prevent.stop="emit('scope',otherTarget!)" @keydown.enter.prevent.stop="emit('scope',otherTarget!)" @keydown.space.prevent.stop="emit('scope',otherTarget!)">{{otherTarget==='user'?'User':'Workspace'}}</a></span><span>)</span></template></span></template>
